def diff_even_odd(arr):
    """
    Find the difference between the first even number and the first odd number in a list.

    Parameters:
        arr (list): A list of integers.

    Returns:
        int or None: The difference (first_even - first_odd) if both exist, otherwise None.
    """
    first_even = None
    first_odd = None

    for num in arr:
        if num % 2 == 0:
            if first_even is None:
                first_even = num
        else:
            if first_odd is None:
                first_odd = num

        # If both are found, return the difference immediately
        if first_even is not None and first_odd is not None:
            return first_even - first_odd

    return None

# Example usage verification
assert diff_even_odd([1, 3, 5, 7, 4, 1, 6, 8]) == 3

def remove_nested(t):
    """
    Removes all nested tuples from a tuple.

    Parameters:
        t (tuple): The input tuple which may contain nested tuples.

    Returns:
        tuple: A new tuple with all nested tuples removed.
    """
    result = []
    for item in t:
        if isinstance(item, tuple):
            # Recursively handle nested tuples
            result.extend(remove_nested(item))
        else:
            result.append(item)
    return tuple(result)

def divisor(n: int) -> int:
    """
    Calculate the number of divisors of a given integer n.

    Parameters:
        n (int): The integer to find the number of divisors for.

    Returns:
        int: The count of divisors of n.
    """
    if n <= 0:
        return 0

    count = 0
    i = 1
    while i * i <= n:
        if n % i == 0:
            if i * i == n:
                count += 1
            else:
                count += 2
        i += 1
    return count

def sequential_search(arr, element):
    """
    Performs a sequential search on a list to find an element.

    Parameters:
        arr (list): The list of elements to search through.
        element: The value to search for in the list.

    Returns:
        tuple: A tuple containing two elements:
            - A boolean indicating whether the element was found (True) or not (False).
            - The index of the element if found, or -1 if not found.
    """
    for index, value in enumerate(arr):
        if value == element:
            return (True, index)
    return (False, -1)

def frequency_lists(data):
    """
    Counts the frequency of each element in a flattened list of lists.

    Parameters:
        data (list of list): A list containing multiple inner lists.

    Returns:
        dict: A dictionary where keys are elements from the input lists 
              and values are their respective counts.
    """
    frequency = {}

    for sublist in data:
        for element in sublist:
            if element in frequency:
                frequency[element] += 1
            else:
                frequency[element] = 1

    return frequency
